SELECT 

WHERE m.academic_term = #{term}

    AND sp.class_name = #{className}


    AND sp.counselor_id = #{scopeCounselorId}


    AND (u.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR u.nickname LIKE CONCAT('%', #{keyword}, '%')
         OR u.username LIKE CONCAT('%', #{keyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR sp.class_name LIKE CONCAT('%', #{keyword}, '%'))


LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)

WHERE m.academic_term = #{term}

    AND sp.class_name = #{className}


    AND sp.counselor_id = #{scopeCounselorId}


    AND (u.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR u.nickname LIKE CONCAT('%', #{keyword}, '%')
         OR u.username LIKE CONCAT('%', #{keyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR sp.class_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT COUNT(*) AS graded, AVG(m.total_score) AS avg_score, MAX(m.total_score) AS max_score, MIN(m.total_score) AS min_score, SUM(CASE WHEN m.grade_level = '优秀' THEN 1 ELSE 0 END) AS excellent, SUM(CASE WHEN m.grade_level = '良好' THEN 1 ELSE 0 END) AS good, SUM(CASE WHEN m.grade_level = '合格' THEN 1 ELSE 0 END) AS pass, SUM(CASE WHEN m.grade_level = '不合格' THEN 1 ELSE 0 END) AS fail
WHERE m.academic_term = #{term}
AND sp.class_name = #{className}
AND sp.counselor_id = #{scopeCounselorId}

